[
  workspace: [
    root: "../..",
    project_globs: ["core/*", "runtime/*"]
  ],
  dependencies: [
    git_dep: [
      opts: [git: "https://example.test/git_dep.git", branch: "main"]
    ]
  ],
  artifacts: [
    monolith_bundle: [
      mode: :monolith,
      roots: ["runtime/api"],
      package: [
        name: "monolith_bundle",
        otp_app: :monolith_bundle,
        version: "0.1.0",
        description: "Fixture bundle generated by weld monolith mode",
        licenses: ["MIT"],
        links: %{"Source" => "https://example.test/monolith_bundle"},
        docs: [
          main: "readme",
          logo: "assets/monolith_bundle.svg",
          homepage_url: "https://example.test/monolith_bundle",
          source_url: "https://example.test/monolith_bundle",
          source_ref: "v0.1.0",
          assets: %{"assets" => "assets"},
          extra_titles: %{
            "README.md" => "Overview",
            "CHANGELOG.md" => "Changelog"
          },
          groups_for_extras: [
            {"Start Here", ["README.md"]},
            {"Release", ["CHANGELOG.md"]}
          ]
        ]
      ],
      output: [
        docs: ["README.md", "CHANGELOG.md", "guides/release.md"],
        assets: ["LICENSE", "assets/monolith_bundle.svg"]
      ]
    ]
  ]
]
